{
  "name": "热释电测量后端",
  "name_en": "Pyroelectric Measurement Backend",
  "manufacturer": "",
  "description": "用于热释电实验的非物理软件组件，负责协调 Lake Shore 350 温度控制器与 Keithley 6517B 的连接和初始配置，执行起始温度稳定、温度斜坡控制，并读取温度与电流测量数据，同时为图形界面提供日志、输入区和曲线显示等支持。",
  "description_en": "A non-physical software component for pyroelectric experiments. It coordinates connection and initial configuration of a Lake Shore 350 temperature controller and a Keithley 6517B, performs start-temperature stabilization and temperature ramp control, acquires temperature and current readings, and supports GUI functions such as logging, input panels, and graph display.",
  "actions": [
    {
      "action_name": "auto-close_instruments",
      "description": "安全关闭并断开已连接仪器。",
      "description_en": "Safely shut down and disconnect the connected instruments."
    },
    {
      "action_name": "auto-initialize_instruments",
      "description": "初始化并配置 Lake Shore 350 与 Keithley 6517B 的通信和测量设置。",
      "description_en": "Initialize and configure communication and measurement settings for the Lake Shore 350 and Keithley 6517B."
    },
    {
      "action_name": "auto-start_ramp",
      "description": "启动温度斜坡并设置升降温速率。",
      "description_en": "Start the temperature ramp and set the ramp rate."
    },
    {
      "action_name": "auto-start_stabilization",
      "description": "启动到起始温度的稳定过程。",
      "description_en": "Start the stabilization process toward the initial temperature."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取当前温度与电流测量值。",
      "description_en": "Get the current temperature and current measurements."
    },
    {
      "action_name": "auto-setup_styles",
      "description": "配置图形界面的显示样式。",
      "description_en": "Set up the visual styles of the graphical interface."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建主界面控件。",
      "description_en": "Create the main user interface widgets."
    },
    {
      "action_name": "auto-create_header",
      "description": "创建界面标题区域。",
      "description_en": "Create the header section of the interface."
    },
    {
      "action_name": "auto-create_info_frame",
      "description": "创建设备或实验信息显示区域。",
      "description_en": "Create the device or experiment information display panel."
    },
    {
      "action_name": "auto-create_input_frame",
      "description": "创建实验参数输入区域。",
      "description_en": "Create the input panel for experiment parameters."
    },
    {
      "action_name": "auto-create_console_frame",
      "description": "创建控制台日志显示区域。",
      "description_en": "Create the console log display panel."
    },
    {
      "action_name": "auto-create_graph_frame",
      "description": "创建测量曲线图显示区域。",
      "description_en": "Create the measurement graph display panel."
    },
    {
      "action_name": "auto-log",
      "description": "记录运行日志信息。",
      "description_en": "Record runtime log messages."
    },
    {
      "action_name": "auto-start_measurement",
      "description": "启动热释电测量流程。",
      "description_en": "Start the pyroelectric measurement process."
    },
    {
      "action_name": "auto-stop_measurement",
      "description": "停止热释电测量流程。",
      "description_en": "Stop the pyroelectric measurement process."
    }
  ],
  "tag_hints": [
    "pyroelectric measurement",
    "temperature ramp control",
    "start-temperature stabilization",
    "Keithley 6517B",
    "Lake Shore 350",
    "current and temperature acquisition",
    "experiment GUI"
  ]
}

